<?php
namespace App\Services;use App\Models\{Insight,InsightRule,Survey,SystemThreshold};use Carbon\CarbonInterface;
class InsightEngineService{
 public function generateForSurvey(Survey $survey,CarbonInterface $from,CarbonInterface $to):array{$created=[];$measurements=$survey->points()->where('validation_status','valid')->with(['measurements'=>fn($q)=>$q->where('is_simulated',false)->whereBetween('captured_at',[$from,$to])])->get()->flatMap->measurements;$rssi=$measurements->pluck('rssi_dbm')->filter(fn($v)=>$v!==null);$download=$measurements->pluck('download_mbps')->filter(fn($v)=>$v!==null);$coverageThreshold=SystemThreshold::number('rssi_weak_dbm',-75);if($rssi->count()>=10&&$this->median($rssi)<=$coverageThreshold)$created[]=$this->persist('RF-001',$survey,$from,$to,['measurement_count'=>$rssi->count(),'median_rssi_dbm'=>$this->median($rssi)],['minimum_measurements'=>10,'weak_rssi_dbm'=>$coverageThreshold],['AP-load telemetry may be unavailable, so congestion cannot be fully excluded.'],'high');$poorThroughput=SystemThreshold::number('throughput_poor_mbps',10);if($download->count()>=5&&$this->median($download)<$poorThroughput)$created[]=$this->persist('PERF-001',$survey,$from,$to,['test_count'=>$download->count(),'median_download_mbps'=>$this->median($download)],['minimum_tests'=>5,'poor_throughput_mbps'=>$poorThroughput],['Low throughput does not by itself identify the cause.'],'medium');$complaints=\App\Models\FeedbackResponse::query()->where('floor_id',$survey->floor_id)->when($survey->survey_area_id,fn($q)=>$q->where('survey_area_id',$survey->survey_area_id))->whereBetween('experienced_at',[$from,$to])->whereHas('correlations')->count();if($complaints>=3)$created[]=$this->persist('UX-001',$survey,$from,$to,['correlated_complaints'=>$complaints],['minimum_correlated_complaints'=>3],[],'medium');return array_values(array_filter($created));}
 private function persist(string $code,Survey $survey,CarbonInterface $from,CarbonInterface $to,array $evidence,array $thresholds,array $limitations,string $confidence):Insight{$rule=InsightRule::where('code',$code)->where('is_active',true)->firstOrFail();$hash=hash('sha256',json_encode([$code,$survey->id,$from->toISOString(),$to->toISOString(),$evidence,$thresholds]));return Insight::updateOrCreate(['evidence_hash'=>$hash],['insight_rule_id'=>$rule->id,'floor_id'=>$survey->floor_id,'survey_area_id'=>$survey->survey_area_id,'survey_id'=>$survey->id,'title'=>$rule->name,'classification'=>$rule->conclusion,'severity'=>$rule->severity,'confidence'=>$confidence,'status'=>'generated','period_start'=>$from,'period_end'=>$to,'evidence'=>$evidence,'triggered_values'=>$evidence,'thresholds'=>$thresholds,'limitations'=>$limitations?:array_filter([$rule->default_limitation]),'recommendation'=>$rule->recommendation,'calculation_version'=>$rule->version,'generated_at'=>now()]);}
 private function median($c):?float{if($c->isEmpty())return null;$s=$c->map(fn($v)=>(float)$v)->sort()->values();$n=$s->count();return round($n%2?$s[intdiv($n,2)]:($s[$n/2-1]+$s[$n/2])/2,3);}}
